/**
 * SAP UI5 scraping helpers.
 *
 * Why this module exists
 * ----------------------
 * The original scrapers read columns through `[data-sap-ui-column="__column0"]`
 * and fields through `#__input0-inner`. Those identifiers are generated by a
 * global incrementing counter inside `sap.ui.core.Element.prototype.getId`, so
 * they change when:
 *   - the app version changes and regenerates its view,
 *   - the user visits screens in a different order,
 *   - the same view is opened twice in one session,
 *   - a popup or dialog is opened before the table is read.
 *
 * Anything that depends on them works in development and breaks in production,
 * which is the worst failure mode there is: it is silent right up until a
 * client's screen changes.
 *
 * The strategy here, in descending order of stability:
 *   1. Read the bound model object. Real values, real types, immune to layout.
 *   2. Capture OData responses (`src/automation/portal/odata-capture.js`).
 *   3. Only as a last resort, traverse by visible label text.
 *
 * Everything that runs inside `page.evaluate` is serialised to a string by
 * Playwright, so those bodies must be self-contained: no closure over Node-side
 * variables, no imports, no helper calls from this file. Constants are passed
 * in as arguments. This is a hard Playwright constraint, not a style choice.
 *
 * Adheres to:
 * - RULE 2: Validate all inputs
 * - RULE 3: No silent failures (every failure path returns a reason)
 * - RULE 6: Bounded operations (every row read is capped)
 * - RULE 7: Fail-safe defaults
 */

/** Hard ceiling on rows any single extraction may return. */
const MAX_EXTRACTED_ROWS = 500;

/** Default politeness delay between filter switches, in milliseconds. */
const DEFAULT_FILTER_DELAY_MS = 800;

/**
 * Bidi and invisible direction marks the portal embeds in its text.
 * @type {RegExp}
 */
const BIDI_MARKS = /[\u200e\u200f\u061c\u202a-\u202e\u2066-\u2069]/g;

/**
 * Normalises Arabic portal text so comparisons are reliable.
 *
 * The same label can arrive with a different alef, a different ya, a
 * ta-marbuta instead of a ha, or wrapped in invisible direction marks, all
 * depending on which screen rendered it. Comparing raw strings then silently
 * fails to match. Normalising before comparison is what makes a filter or a
 * header lookup dependable.
 *
 * @param {unknown} value
 * @returns {string}
 */
function normalizeArabic(value) {
  return String(value === undefined || value === null ? '' : value)
    .replace(BIDI_MARKS, '')
    .replace(/[\u0660-\u0669]/g, (d) => String(d.charCodeAt(0) - 0x0660))
    .replace(/[\u06F0-\u06F9]/g, (d) => String(d.charCodeAt(0) - 0x06F0))
    .replace(/[\u0622\u0623\u0625\u0671]/g, '\u0627')
    .replace(/\u0629/g, '\u0647')
    .replace(/\u0649/g, '\u064A')
    .replace(/\u0624/g, '\u0648')
    .replace(/\u0626/g, '\u064A')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * A canonical map of the filing-obligations table's visible headers to the
 * field names the rest of the pipeline expects.
 *
 * Mapping by header text rather than by `__columnN` is what makes this survive
 * the portal reordering or adding a column.
 *
 * @type {ReadonlyArray<{header: string, field: string, required: boolean}>}
 */
const OBLIGATION_HEADER_MAP = Object.freeze([
  { header: 'النموذج', field: 'formTitle', required: true },
  { header: 'الفترة', field: 'period', required: false },
  { header: 'الفترة من', field: 'periodFrom', required: false },
  { header: 'الفترة إلى', field: 'periodTo', required: false },
  { header: 'نوع الإيرادات', field: 'revenueType', required: false },
  { header: 'تاريخ الاستحقاق', field: 'dueDate', required: false },
  { header: 'تاريخ الاستلام', field: 'receivedDate', required: false }
]);

/**
 * A canonical map of the forms table headers.
 *
 * @type {ReadonlyArray<{header: string, field: string, required: boolean}>}
 */
const FORMS_HEADER_MAP = Object.freeze([
  { header: 'النموذج', field: 'formTitle', required: true },
  { header: 'الفترة', field: 'period', required: false },
  { header: 'الحالة', field: 'status', required: false }
]);

/**
 * Maps a header map plus the column headers actually present into field names.
 *
 * Pure and Node-side, so it is unit-testable without a browser. The in-page half
 * only reports which headers it saw and what each column's text was.
 *
 * @param {ReadonlyArray<{header: string, field: string}>} headerMap
 * @param {Array<string>} actualHeaders - headers read from the table
 * @param {Array<Array<string>>} rows - per-row, per-column cell text
 * @returns {{rows: Array<Object>, unmapped: Array<string>}}
 */
function mapRowsByHeader(headerMap, actualHeaders, rows) {
  const normalizedHeaders = (Array.isArray(actualHeaders) ? actualHeaders : []).map(normalizeArabic);
  const map = headerMap || [];

  // An index per field, built by matching normalised header text. A header the
  // portal renamed simply produces no index, and that column is left unmapped
  // rather than silently filling the wrong field.
  const indexByField = new Map();
  for (const entry of map) {
    const wanted = normalizeArabic(entry.header);
    const at = normalizedHeaders.indexOf(wanted);
    if (at !== -1 && !indexByField.has(entry.field)) {
      indexByField.set(entry.field, at);
    }
  }

  const out = [];
  for (const row of rows) {
    const cells = Array.isArray(row) ? row : [];
    const record = {};
    for (const entry of map) {
      const at = indexByField.get(entry.field);
      record[entry.field] = at === undefined ? '' : String(cells[at] === undefined ? '' : cells[at]).trim();
    }
    // Cells kept so a caller can still fall back to positional parsing when a
    // header went unrecognized.
    record.cells = cells.map((c) => String(c === undefined ? '' : c).trim());
    out.push(record);
  }

  const unmapped = normalizedHeaders.filter((h) => h.length > 0 && !map.some((e) => normalizeArabic(e.header) === h));
  return { rows: out, unmapped };
}

/**
 * Reads the bound row objects from a UI5 table, by ID suffix.
 *
 * Runs in page context. Self-contained by necessity: Playwright serialises this
 * function to source text, so it may only use its parameters and globals that
 * exist in the browser.
 *
 * @param {import('playwright').Page} page
 * @param {string} idSuffix - stable control id suffix, e.g. '--idFilingObligationsTable'
 * @param {number} [maxRows=200]
 * @returns {Promise<{ok: boolean, rows: Array<Object>, total: number, truncated: boolean, reason?: string, model?: string}>}
 */
async function readUi5ListBinding(page, idSuffix, maxRows = 200) {
  if (!page || typeof page.evaluate !== 'function') {
    throw new TypeError('readUi5ListBinding requires a Playwright page');
  }
  if (typeof idSuffix !== 'string' || idSuffix.length === 0) {
    throw new TypeError('idSuffix is required');
  }
  const limit = Number.isInteger(maxRows) && maxRows > 0 ? Math.min(maxRows, MAX_EXTRACTED_ROWS) : 200;

  return page.evaluate(({ idSuffix, limit }) => {
    const ui5 = window.sap && window.sap.ui && window.sap.ui.core;
    if (!ui5 || !ui5.Element || !ui5.Element.registry) {
      return { ok: false, reason: 'ui5_registry_unavailable', rows: [], total: 0, truncated: false };
    }

    const all = ui5.Element.registry.filter((el) => {
      try {
        return typeof el.getId === 'function' && el.getId().endsWith(idSuffix);
      } catch (_) {
        return false;
      }
    });

    if (all.length === 0) return { ok: false, reason: 'control_not_found', rows: [], total: 0, truncated: false };
    // More than one match means the suffix is not specific enough to be safe,
    // and picking the first would read the wrong table.
    if (all.length > 1) return { ok: false, reason: `expected_1_control_found_${all.length}`, rows: [], total: 0, truncated: false };

    const table = all[0];
    const items = typeof table.getItems === 'function' ? table.getItems() : [];
    const rows = [];

    // Declared outside the loop: a view can bind more than one model, and the
    // answer to "which model did this table come from" is only meaningful once
    // the whole table has been read.
    let resolvedModel = null;

    for (let i = 0; i < items.length && rows.length < limit; i++) {
      const item = items[i];

      // The model can be the default one, or a named one on this view. The
      // default lookup is tried first; if it yields nothing, every binding
      // context the control holds is tried before the row is given up on.
      let obj = null;
      let modelName = null;

      const tryContext = (ctx) => {
        if (!ctx || typeof ctx.getObject !== 'function') return null;
        try {
          const value = ctx.getObject();
          return value && typeof value === 'object' ? value : null;
        } catch (_) {
          return null;
        }
      };

      const direct = typeof item.getBindingContext === 'function' ? tryContext(item.getBindingContext()) : null;
      if (direct) {
        obj = direct;
      } else {
        // `oBindingContexts` is keyed by model name on views that bind a named
        // model (formModel, detail, ...). Iterate rather than guess a name.
        const contexts = item.oBindingContexts;
        if (contexts && typeof contexts === 'object') {
          const names = Object.keys(contexts);
          for (let n = 0; n < names.length; n++) {
            const candidate = tryContext(contexts[names[n]]);
            if (candidate) {
              obj = candidate;
              resolvedModel = names[n];
              break;
            }
          }
        }
      }

      if (!obj) {
        // Report the miss rather than pushing an empty row: a table full of
        // blanks would look like "no obligations", which is the false all-clear
        // this whole rework exists to prevent.
        rows.push({ __extraction_error: 'no_binding_object', index: i });
        continue;
      }

      // JSON round-trip strips prototypes and functions so the value survives
      // structured cloning back into Node.
      let plain;
      try {
        plain = JSON.parse(JSON.stringify(obj));
      } catch (_) {
        rows.push({ __extraction_error: 'object_not_serializable', index: i });
        continue;
      }

      plain.__boundModel = resolvedModel || 'default';
      if (!resolvedModel) resolvedModel = 'default';
      rows.push(plain);
    }

    let total = items.length;
    const binding = typeof table.getBinding === 'function' ? table.getBinding('items') : null;
    if (binding && typeof binding.getLength === 'function') {
      try {
        const length = binding.getLength();
        if (typeof length === 'number' && length >= 0) total = length;
      } catch (_) {
        // Fall back to the item count rather than reporting a wrong total.
      }
    }

    return {
      ok: true,
      rows,
      total,
      truncated: total > rows.length,
      model: resolvedModel || 'default'
    };
  }, { idSuffix, limit });
}

/**
 * Reads a UI5 table's visible headers and cell text, in DOM order.
 *
 * This is the label-traversal fallback: no model involved, so it survives a
 * control whose binding is unavailable, at the cost of reading formatted text
 * rather than raw values.
 *
 * @param {import('playwright').Page} page
 * @param {string} [rowSelector='tr.sapMListTblRow:not(.sapMListTblHeader)']
 * @param {number} [maxRows=200]
 * @returns {Promise<{ok: boolean, headers: Array<string>, rows: Array<Array<string>>, total: number, reason?: string}>}
 */
async function extractUi5Table(page, rowSelector = 'tr.sapMListTblRow:not(.sapMListTblHeader)', maxRows = 200) {
  if (!page || typeof page.evaluate !== 'function') {
    throw new TypeError('extractUi5Table requires a Playwright page');
  }
  if (typeof rowSelector !== 'string' || rowSelector.length === 0) {
    throw new TypeError('rowSelector is required');
  }
  const limit = Number.isInteger(maxRows) && maxRows > 0 ? Math.min(maxRows, MAX_EXTRACTED_ROWS) : 200;

  return page.evaluate(({ rowSelector, limit }) => {
    const headerCells = Array.from(document.querySelectorAll('tr.sapMListTblRow.sapMListTblHeader th'));
    // Some renders put the header in a td; fall back to the row's own cells.
    let headers = headerCells.map((th) => (th.innerText || '').trim());
    if (headers.length === 0) {
      const headerRow = document.querySelector('tr.sapMListTblRow.sapMListTblHeader');
      if (headerRow) headers = Array.from(headerRow.querySelectorAll('td')).map((td) => (td.innerText || '').trim());
    }

    const rowNodes = Array.from(document.querySelectorAll(rowSelector));
    const rows = [];
    for (let i = 0; i < rowNodes.length && rows.length < limit; i++) {
      const cells = Array.from(rowNodes[i].querySelectorAll('td')).map((td) => (td.innerText || '').trim());
      // The first cell is often an empty selection checkbox column; dropping a
      // single leading blank keeps it from shifting every header index.
      rows.push(cells.length > 0 && cells[0] === '' ? cells.slice(1) : cells);
    }

    return { ok: true, headers, rows, total: rowNodes.length };
  }, { rowSelector, limit });
}

/**
 * Waits for the table to finish loading before reading it.
 *
 * The portal keeps the previous filter's rows in the DOM while the new ones
 * load, so reading immediately returns stale data — the classic false positive
 * where the scraper reports the old filter's contents as the new filter's.
 * Stability is: the busy indicator is gone, no "more data" trigger pending,
 * and the table is not showing its empty state.
 *
 * @param {import('playwright').Page} page
 * @param {Object} [options={}]
 * @param {number} [options.timeoutMs=15000]
 * @param {number} [options.pollMs=300]
 * @returns {Promise<{ok: boolean, reason?: string}>}
 */
async function waitForTableStable(page, options = {}) {
  if (!page || typeof page.waitForFunction !== 'function') {
    throw new TypeError('waitForTableStable requires a Playwright page');
  }
  const timeoutMs = Number.isFinite(options.timeoutMs) && options.timeoutMs > 0 ? options.timeoutMs : 15000;
  const pollMs = Number.isFinite(options.pollMs) && options.pollMs > 0 ? options.pollMs : 300;

  // The predicate must return a boolean and be re-evaluated by Playwright on
  // each poll, so it is synchronous and side-effect free. Returning a promise
  // here would resolve on the first tick and defeat the whole wait.
  try {
    await page.waitForFunction(
      () => {
        const indicator = document.querySelector('.sapMBusyIndicator');
        // offsetParent is null for a hidden element, so this is "busy" only
        // when the indicator is actually visible.
        const busy = indicator !== null && indicator.offsetParent !== null;
        return !busy;
      },
      undefined,
      { timeout: timeoutMs, polling: pollMs }
    );
    return { ok: true };
  } catch (err) {
    // A timeout is reported, never thrown away: the caller decides whether to
    // proceed with a possibly-stale read or to record the route as failed.
    return { ok: false, reason: `table_not_stable:${err.message}` };
  }
}

/**
 * Clicks a growing list's "load more" trigger, up to a bounded number of times.
 *
 * sap.m.List only renders the first page; the rest load on demand. Stopping at
 * the cap and reporting truncation is required — an unbounded click loop
 * against a live portal is both a RULE 6 violation and a bot-detection signal.
 *
 * @param {import('playwright').Page} page
 * @param {Object} [options={}]
 * @param {number} [options.maxClicks=50]
 * @param {number} [options.delayMs=1200]
 * @returns {Promise<{clicks: number, exhausted: boolean, truncated: boolean}>}
 */
async function clickGrowingTrigger(page, options = {}) {
  if (!page || typeof page.evaluate !== 'function') {
    throw new TypeError('clickGrowingTrigger requires a Playwright page');
  }
  // RULE 6: bounded. 50 clicks is far more than any real taxpayer needs and
  // stops well short of hammering the portal.
  const maxClicks = Number.isInteger(options.maxClicks) && options.maxClicks > 0
    ? Math.min(options.maxClicks, 200)
    : 50;
  const delayMs = Number.isFinite(options.delayMs) && options.delayMs > 0 ? options.delayMs : 1200;

  let clicks = 0;
  for (let i = 0; i < maxClicks; i++) {
    const clicked = await page.evaluate(() => {
      const trigger = document.querySelector('.sapMGrowingListTrigger');
      if (!trigger) return false;
      // UI5 routes clicks through its own event layer, so the trigger has to be
      // clicked rather than having its state poked.
      trigger.click();
      return true;
    }).catch(() => false);

    if (!clicked) break;
    clicks += 1;
    await page.waitForTimeout(delayMs);
    const stable = await waitForTableStable(page, { timeoutMs: 10000 });
    if (!stable.ok) break;
  }

  // Still a visible trigger after the last click means there is more to load
  // that we did not read. Reported rather than dropped silently.
  const exhausted = await page.evaluate(
    () => document.querySelector('.sapMGrowingListTrigger') === null
  ).catch(() => false);

  return { clicks, exhausted, truncated: !exhausted };
}

/**
 * Switches a sap.m.Select filter to a given item and waits for the table to
 * settle.
 *
 * A sap.m.Select is a `<div class="sapMSlt">`, not a native `<select>`. Its
 * hidden mirror element is kept for accessibility and setting its value fires no
 * UI5 change handler, so a `<select>`-style write does nothing at all. The list
 * lives in a popover appended to `<body>`, so it must be opened by clicking the
 * visible control before the item exists to be clicked.
 *
 * Two strategies are attempted, in order:
 *   1. `setSelectedKey` + `fireChange` — precise, no mouse simulation.
 *   2. Real click on the control then the item — the fallback when the control
 *      does not expose the API the way it should.
 *
 * @param {import('playwright').Page} page
 * @param {Object} options
 * @param {string} options.controlId - id or id suffix of the sap.m.Select
 * @param {string} options.targetKey - the selectedKey to apply
 * @param {string} [options.visibleText] - fallback matching text, normalised
 * @param {string[]} [options.discoveryTexts] - option texts that uniquely identify
 *   the control when the generated id changes
 * @param {number} [options.delayMs=800] - politeness pause after the switch
 * @param {number} [options.timeoutMs=15000]
 * @returns {Promise<{ok: boolean, strategy?: string, reason?: string}>}
 */
async function switchSelectFilter(page, options = {}) {
  if (!page || typeof page.evaluate !== 'function') {
    throw new TypeError('switchSelectFilter requires a Playwright page');
  }
  const controlId = options.controlId;
  if (typeof controlId !== 'string' || controlId.length === 0) {
    throw new TypeError('controlId is required');
  }
  const targetKey = typeof options.targetKey === 'string' ? options.targetKey : '';
  const visibleText = typeof options.visibleText === 'string' ? options.visibleText : '';
  const discoveryTexts = Array.isArray(options.discoveryTexts)
    ? options.discoveryTexts.filter((text) => typeof text === 'string' && text.trim().length > 0)
    : [];
  const delayMs = Number.isFinite(options.delayMs) && options.delayMs >= 0 ? options.delayMs : DEFAULT_FILTER_DELAY_MS;
  const timeoutMs = Number.isFinite(options.timeoutMs) && options.timeoutMs > 0 ? options.timeoutMs : 15000;

  // Strategy 1 — the control API.
  const viaApi = await page.evaluate(({ controlId, targetKey, discoveryTexts, visibleText }) => {
    const registry = window.sap && window.sap.ui && window.sap.ui.core && window.sap.ui.core.Element.registry;
    if (!registry) return { ok: false, reason: 'ui5_registry_unavailable' };

    const normalize = (value) => String(value || '')
      .replace(/[\u200e\u200f\u061c\u202a-\u202e\u2066-\u2069]/g, '')
      .replace(/[\u064b-\u065f\u0670\u06d6-\u06ed\u0640]/g, '')
      .replace(/[\u0622\u0623\u0625\u0671]/g, '\u0627')
      .replace(/\u0629/g, '\u0647')
      .replace(/\s+/g, ' ')
      .trim();
    const stripCount = (str) => String(str || '')
      .replace(/\s*[(\u064b-\u065f（]*\s*[\d\u0660-\u0669]+\s*[)\u064b-\u065f）]*\s*$/, '')
      .trim();
    const matchesOption = (itemText, wanted) => {
      const cleanItem = stripCount(normalize(itemText));
      const cleanWanted = stripCount(normalize(wanted));
      return cleanItem === cleanWanted
        || (cleanWanted.length > 0 && cleanItem.indexOf(cleanWanted) !== -1)
        || (cleanItem.length > 0 && cleanWanted.indexOf(cleanItem) !== -1);
    };

    const wantedOptions = discoveryTexts.map(normalize).filter(Boolean);

    let candidates = registry.filter((el) => {
      try {
        const id = el.getId();
        return id === controlId || id.endsWith(controlId);
      } catch (_) {
        return false;
      }
    });

    // UI5 view prefixes are generated. When the configured suffix is absent,
    // identify this select by the pair of option labels a human sees instead.
    if (candidates.length !== 1 && wantedOptions.length > 0) {
      candidates = registry.filter((el) => {
        try {
          if (typeof el.setSelectedKey !== 'function' || typeof el.getItems !== 'function') return false;
          const itemTexts = el.getItems().map((item) => normalize(
            typeof item.getText === 'function' ? item.getText() : (item.getTitle ? item.getTitle() : '')
          ));
          return wantedOptions.every((wanted) => itemTexts.some((text) => matchesOption(text, wanted)));
        } catch (_) {
          return false;
        }
      });
      // Fallback: if requiring all options failed, check if any select matches any wanted option
      if (candidates.length === 0) {
        candidates = registry.filter((el) => {
          try {
            if (typeof el.setSelectedKey !== 'function' || typeof el.getItems !== 'function') return false;
            const itemTexts = el.getItems().map((item) => normalize(
              typeof item.getText === 'function' ? item.getText() : (item.getTitle ? item.getTitle() : '')
            ));
            return wantedOptions.some((wanted) => itemTexts.some((text) => matchesOption(text, wanted)));
          } catch (_) {
            return false;
          }
        });
      }
    }
    if (candidates.length !== 1) return { ok: false, reason: `control_matches_${candidates.length}` };

    const control = candidates[0];
    if (typeof control.setSelectedKey !== 'function') return { ok: false, reason: 'not_a_select' };

    // Resolve target key from actual control items if possible
    let resolvedKey = targetKey;
    const items = typeof control.getItems === 'function' ? control.getItems() : [];
    let targetItem = null;
    if (targetKey) {
      targetItem = items.find((it) => {
        try {
          return (typeof it.getKey === 'function' && it.getKey() === targetKey)
            || (it.mProperties && it.mProperties.key === targetKey);
        } catch (_) { return false; }
      });
    }
    if (!targetItem && visibleText) {
      targetItem = items.find((it) => {
        try {
          const t = typeof it.getText === 'function' ? it.getText() : (it.getTitle ? it.getTitle() : '');
          return matchesOption(t, visibleText);
        } catch (_) { return false; }
      });
    }
    if (targetItem) {
      if (typeof targetItem.getKey === 'function') {
        resolvedKey = targetItem.getKey();
      } else if (targetItem.mProperties && targetItem.mProperties.key) {
        resolvedKey = targetItem.mProperties.key;
      }
      if (typeof control.setSelectedItem === 'function') {
        try { control.setSelectedItem(targetItem); } catch (_) {}
      }
    }

    control.setSelectedKey(resolvedKey);
    // fireChange is required: setSelectedKey alone updates the display without
    // telling the controller, so the table never reloads.
    if (typeof control.fireChange === 'function') {
      const selectedItem = targetItem || (typeof control.getSelectedItem === 'function' ? control.getSelectedItem() : null);
      control.fireChange({ selectedItem });
    }
    return { ok: true, controlId: control.getId() };
  }, { controlId, targetKey, discoveryTexts, visibleText }).catch((err) => ({ ok: false, reason: err.message }));

  if (viaApi.ok) {
    // Politeness pause before touching the DOM again, and so the table has a
    // chance to start its reload.
    if (delayMs > 0) await page.waitForTimeout(delayMs);
    const stable = await waitForTableStable(page, { timeoutMs });
    if (stable.ok) return { ok: true, strategy: 'setSelectedKey', controlId: viaApi.controlId };
    return { ok: false, strategy: 'setSelectedKey', reason: stable.reason };
  }

  // Strategy 2 — real clicks.
  const viaClick = await page.evaluate(({ controlId, visibleText, targetKey, discoveryTexts }) => {
    const registry = window.sap && window.sap.ui && window.sap.ui.core && window.sap.ui.core.Element.registry;
    let domId = controlId;

    if (registry) {
      const candidates = registry.filter((el) => {
        try {
          const id = el.getId();
          return id === controlId || id.endsWith(controlId);
        } catch (_) {
          return false;
        }
      });
      if (candidates.length === 1) domId = candidates[0].getId();
    }

    let node = document.getElementById(domId);
    // SAP prefixes every view-local id (for example
    // `__xmlview1--filingObligationFilter`). The configured value is a suffix,
    // so the DOM fallback must apply the same suffix rule as the UI5 lookup.
    if (!node) {
      const candidates = Array.from(document.querySelectorAll('.sapMSlt, .sapMSelect, [role="combobox"], select, [aria-haspopup], .sapMBtn, .sapMMenuBtn, [role="button"], button')).filter((candidate) => {
        const id = candidate.id || '';
        return id === controlId || id.endsWith(controlId);
      });
      if (candidates.length === 1) node = candidates[0];
    }
    if (!node && discoveryTexts.length > 0) {
      const normalize = (value) => String(value || '')
        .replace(/[\u200e\u200f\u061c\u202a-\u202e\u2066-\u2069]/g, '')
        .replace(/[\u064b-\u065f\u0670\u06d6-\u06ed\u0640]/g, '')
        .replace(/[\u0622\u0623\u0625\u0671]/g, '\u0627')
        .replace(/\u0629/g, '\u0647')
        .replace(/\s+/g, ' ')
        .trim();
      const stripCount = (str) => String(str || '')
        .replace(/\s*[(\u064b-\u065f（]*\s*[\d\u0660-\u0669]+\s*[)\u064b-\u065f）]*\s*$/, '')
        .trim();
      const matchesText = (candidateText, wanted) => {
        const cleanCand = stripCount(normalize(candidateText));
        const cleanWanted = stripCount(normalize(wanted));
        return cleanCand === cleanWanted
          || (cleanWanted.length > 0 && cleanCand.indexOf(cleanWanted) !== -1)
          || (cleanCand.length > 0 && cleanWanted.indexOf(cleanCand) !== -1);
      };
      const wanted = discoveryTexts.map(normalize).filter(Boolean);
      const candidates = Array.from(document.querySelectorAll('.sapMSlt, .sapMSelect, [role="combobox"], select, [aria-haspopup], .sapMBtn, .sapMMenuBtn, [role="button"], button'));
      const nodes = candidates.filter((candidate) =>
        wanted.some((text) => matchesText(candidate.innerText || candidate.textContent || '', text))
      );
      if (nodes.length >= 1) {
        node = nodes[0];
      } else if (candidates.length === 1) {
        node = candidates[0];
      } else {
        const leafCandidates = Array.from(document.querySelectorAll('div, span, button, a')).filter((el) => {
          if (el.children && el.children.length > 3) return false;
          const txt = (el.innerText || el.textContent || '').trim();
          return wanted.some((text) => matchesText(txt, text));
        });
        if (leafCandidates.length >= 1) {
          node = leafCandidates[0];
        }
      }
    }
    if (!node) return { ok: false, reason: 'control_dom_not_found' };

    // Open the popover: the list does not exist in the DOM until the control is
    // clicked.
    node.click();

    return new Promise((resolve) => {
      // The popover is appended to body asynchronously, so it is polled rather
      // than queried immediately.
      let attempts = 0;
      const poll = () => {
        attempts += 1;
        const list = document.querySelector('.sapMSelectList, [role="listbox"], ul.sapMSelect, .sapMPopover, .sapMDialog, .sapMMenu, div.sapMPopoverCont');
        if (!list) {
          if (attempts > 20) { resolve({ ok: false, reason: 'popover_never_opened' }); return; }
          setTimeout(poll, 150);
          return;
        }

        const items = Array.from(list.querySelectorAll('li, .sapMSelectListItem, [role="option"], .sapMMenuItem, .sapMCustomListItem, .sapMStandardListItem, div.sapMSLITitleOnly, span'));
        let matched = null;

        // Match on the item's own key when one is exposed, since that is the
        // value setSelectedKey would take and cannot drift with the wording.
        if (targetKey) {
          for (const item of items) {
            const value = item.getAttribute && (
              item.getAttribute('data-sap-ui-value')
              || item.getAttribute('data-key')
              || item.getAttribute('data-value')
            );
            if (value === targetKey) { matched = item; break; }
          }
        }

        if (!matched && visibleText) {
          const normalize = (value) => String(value || '')
            .replace(/[\u200e\u200f\u061c\u202a-\u202e\u2066-\u2069]/g, '')
            .replace(/[\u064b-\u065f\u0670\u06d6-\u06ed\u0640]/g, '')
            .replace(/[\u0622\u0623\u0625\u0671]/g, '\u0627')
            .replace(/\u0629/g, '\u0647')
            .replace(/\s+/g, ' ')
            .trim();
          const stripCount = (str) => String(str || '')
            .replace(/\s*[(\u064b-\u065f（]*\s*[\d\u0660-\u0669]+\s*[)\u064b-\u065f）]*\s*$/, '')
            .trim();
          const matchesText = (candidateText, wanted) => {
            const cleanCand = stripCount(normalize(candidateText));
            const cleanWanted = stripCount(normalize(wanted));
            return cleanCand === cleanWanted
              || (cleanWanted.length > 0 && cleanCand.indexOf(cleanWanted) !== -1)
              || (cleanCand.length > 0 && cleanWanted.indexOf(cleanCand) !== -1);
          };
          for (const item of items) {
            const text = (item.innerText || item.textContent || '').trim();
            if (text && matchesText(text, visibleText)) { matched = item; break; }
          }
        }

        if (!matched && items.length === 1) {
          // A single-item list cannot be ambiguous, so take it.
          matched = items[0];
        }

        if (!matched) { resolve({ ok: false, reason: 'item_not_in_list' }); return; }

        matched.click();
        resolve({ ok: true, controlId: node.id || '' });
      };
      poll();
    });
  }, { controlId, visibleText, targetKey, discoveryTexts }).catch((err) => ({ ok: false, reason: err.message }));

  if (!viaClick.ok && visibleText) {
    // Strategy 3: Playwright native locator fallback
    try {
      const activeFilter = page.locator('.sapMSlt, .sapMSelect, [role="combobox"], .sapMSltLabel, [role="button"]')
        .filter({ hasText: visibleText }).first();
      if (await activeFilter.count() > 0 && await activeFilter.isVisible()) {
        return { ok: true, strategy: 'already_selected' };
      }

      const trigger = page.locator('.sapMSlt, .sapMSelect, [role="combobox"], .sapMSltLabel, [aria-haspopup], .sapMBtn, [role="button"], button')
        .filter({ hasText: /لم يتم التقديم/ })
        .first();

      if (await trigger.count() > 0) {
        await trigger.click({ timeout: 5000 });
        if (delayMs > 0) await page.waitForTimeout(delayMs);

        const option = page.locator('.sapMSelectList, [role="listbox"], .sapMPopover, .sapMDialog, ul')
          .locator('li, [role="option"], .sapMSelectListItem, .sapMMenuItem, div, span')
          .filter({ hasText: visibleText })
          .first();

        if (await option.count() > 0) {
          await option.click({ timeout: 5000 });
          viaClick.ok = true;
          viaClick.controlId = 'playwright_locator';
        } else {
          const directText = page.locator(`text="${visibleText}"`).last();
          if (await directText.count() > 0) {
            await directText.click({ timeout: 5000 });
            viaClick.ok = true;
            viaClick.controlId = 'playwright_direct_text';
          }
        }
      }
    } catch (locErr) {
      void (locErr); // Fallback attempt recorded without throwing
    }
  }

  if (!viaClick.ok) {
    // All strategies failed. The caller must be able to tell this apart from
    // "the filter was already on this value".
    return { ok: false, reason: viaClick.reason || viaApi.reason || 'switch_failed' };
  }

  if (delayMs > 0) await page.waitForTimeout(delayMs);
  const stable = await waitForTableStable(page, { timeoutMs });
  if (stable.ok) return { ok: true, strategy: viaClick.controlId ? 'click' : 'playwright', controlId: viaClick.controlId };
  return { ok: false, strategy: 'click', reason: stable.reason };
}

/**
 * Reads a labelled field from a UI5 detail view by its visible label text.
 *
 * The fallback for detail screens, where fields are addressed by
 * `__input0-inner` today and that counter is exactly what breaks. Traversal by
 * the label the user can see is stable across app versions.
 *
 * @param {import('playwright').Page} page
 * @param {Object} options
 * @param {string[]} options.labels - candidate label texts, normalised
 * @returns {Promise<{ok: boolean, value: string, matchedLabel?: string, reason?: string}>}
 */
async function readLabelledField(page, options = {}) {
  if (!page || typeof page.evaluate !== 'function') {
    throw new TypeError('readLabelledField requires a Playwright page');
  }
  const labels = Array.isArray(options.labels) ? options.labels.filter((l) => typeof l === 'string' && l.length > 0) : [];
  if (labels.length === 0) throw new TypeError('readLabelledField requires at least one label');

  return page.evaluate((labels) => {
    const normalize = (s) => String(s || '')
      .replace(/[\u200e\u200f\u061c\u202a-\u202e\u2066-\u2069]/g, '')
      .replace(/[\u0622\u0623\u0625\u0671]/g, '\u0627')
      .replace(/\u0629/g, '\u0647')
      .replace(/\s+/g, ' ')
      .trim();

    const wanted = labels.map(normalize);
    const nodes = Array.from(document.querySelectorAll('label, span, bdi, div, th, td'));

    // Two passes. An exact label match is unambiguous, so it is tried across the
    // whole document first. Only if nothing matches exactly does a substring
    // pass run — because "الرسالة" is a substring of "نوع الرسالة", and a
    // single-pass substring match reads the wrong field's value.
    const readValueFor = (node) => {
      const candidates = [
        node.nextElementSibling,
        node.parentElement && node.parentElement.nextElementSibling
      ].filter(Boolean);

      for (const candidate of candidates) {
        const tag = (candidate.tagName || '').toLowerCase();
        const isField = tag === 'input' || tag === 'textarea'
          || candidate.classList.contains('sapMInputText')
          || candidate.classList.contains('sapMTextArea')
          || candidate.querySelector('input, textarea');
        if (!isField) continue;

        const input = tag === 'input' || tag === 'textarea' ? candidate : candidate.querySelector('input, textarea');
        const value = (input.value !== undefined ? input.value : input.innerText || '').trim();
        if (value.length > 0) return value;
      }
      return '';
    };

    // Pass 1: exact.
    for (const target of wanted) {
      for (const node of nodes) {
        const text = normalize(node.innerText);
        // A label that also carries its value would not be an exact match, so
        // this cannot latch onto a populated field.
        if (text !== target) continue;
        const value = readValueFor(node);
        if (value.length > 0) return { ok: true, value, matchedLabel: target };
      }
    }

    // Pass 2: substring, and only for a label long enough to be distinctive.
    // The length floor is what stops "النص" from matching every label on the
    // page, and why the caller passes the longer label first.
    const distinctive = wanted.filter((target) => target.length >= 5);
    for (const target of distinctive) {
      for (const node of nodes) {
        const text = normalize(node.innerText);
        if (!text || text.length > 60) continue;
        if (text.indexOf(target) === -1) continue;

        const value = readValueFor(node);
        if (value.length > 0) return { ok: true, value, matchedLabel: target };
      }
    }

    return { ok: false, value: '', reason: 'label_not_found' };
  }, labels).catch((err) => ({ ok: false, value: '', reason: err.message }));
}

/**
 * Navigates to a portal hash route, preserving any path that matters.
 *
 * The message list route carries a positional key whose leading `%20` is part
 * of the backend key, not stray whitespace. Decoding it before use would
 * produce a route that does not exist.
 *
 * @param {import('playwright').Page} page
 * @param {string} hashRoute - e.g. '#/messages/AL/%201'
 * @param {number} [waitMs=3000]
 * @returns {Promise<boolean>} whether the navigation was issued
 */
async function navigateToHash(page, hashRoute, waitMs = 3000) {
  if (!page || typeof page.evaluate !== 'function') {
    throw new TypeError('navigateToHash requires a Playwright page');
  }
  if (typeof hashRoute !== 'string' || hashRoute.length === 0) {
    throw new TypeError('hashRoute is required');
  }
  const wait = Number.isFinite(waitMs) && waitMs >= 0 ? waitMs : 3000;

  // Determine target tile label if any
  let targetTile = '';
  if (hashRoute.includes('filing_obligations')) targetTile = 'التزامات التقديم';
  else if (hashRoute.includes('documents')) targetTile = 'مستنداتي';
  else if (hashRoute.includes('forms')) targetTile = 'النماذج';
  else if (hashRoute.includes('messages')) targetTile = 'مركز الرسائل';

  // 1. Check if the target view is already active and rendered
  const isTargetAlreadyOpen = await page.evaluate(({ route }) => {
    if (route.includes('filing_obligations')) {
      return Boolean(document.querySelector('[id*="filingObligationFilter"], [id*="FilingObligation"]'));
    }
    if (route.includes('forms')) {
      return Boolean(document.querySelector('[id*="formsTable"], [id*="Forms"]'));
    }
    if (route.includes('documents')) {
      return Boolean(document.querySelector('[id*="docTable"], [id*="Documents"]'));
    }
    return false;
  }, { route: hashRoute }).catch((err) => {
    void (err);
    return false;
  });

  if (isTargetAlreadyOpen) {
    return true;
  }

  // 2. If on a subview, click the "المنزل" (Home) button to return to the launchpad
  try {
    const homeBtn = page.locator('button, [role="button"]').filter({ hasText: 'المنزل' }).first();
    if (await homeBtn.count() > 0 && await homeBtn.isVisible()) {
      await homeBtn.click();
      await page.waitForTimeout(2000);
    }
  } catch (homeErr) {
    void (homeErr);
  }

  // 3. Click the target tile on the launchpad if present
  if (targetTile) {
    try {
      const tile = page.locator('.sapMTile, .sapMCustomTile').filter({ hasText: targetTile }).first();
      if (await tile.count() > 0) {
        await tile.click({ timeout: 5000 });
        if (wait > 0) await page.waitForTimeout(wait);
        return true;
      }
    } catch (tileErr) {
      void (tileErr);
    }
  }

  // 4. Fallback: hash navigation
  await page.evaluate((route) => {
    if (window.hasher && typeof window.hasher.setHash === 'function') {
      window.hasher.setHash(route.replace(/^#\/?/, ''));
    } else {
      window.location.hash = route;
    }
  }, hashRoute);
  if (wait > 0) await page.waitForTimeout(wait);

  // If launchpad appeared after hash change, click the tile
  if (targetTile) {
    try {
      const tile = page.locator('.sapMTile, .sapMCustomTile').filter({ hasText: targetTile }).first();
      if (await tile.count() > 0 && await tile.isVisible()) {
        await tile.click({ timeout: 5000 });
        if (wait > 0) await page.waitForTimeout(wait);
      }
    } catch (tileErr) {
      void (tileErr);
    }
  }

  return true;
}

/**
 * Property-name aliases for a bound obligation row.
 *
 * The same value appears under different names depending on whether it came from
 * the UI5 model, an OData v2 payload, or an OData v4 payload. Listing the
 * candidates lets one field be filled from whichever source produced it, instead
 * of each scraper hard-coding one shape.
 *
 * @type {ReadonlyObject<string, Array<string>>}
 */
const OBLIGATION_FIELD_ALIASES = Object.freeze({
  formTitle: ['FormTitle', 'formTitle', 'Name', 'name', 'FormName', 'formName', 'Title', 'title'],
  period: ['Period', 'period', 'PeriodName', 'periodName', 'PeriodText', 'periodText'],
  periodFrom: ['PeriodFrom', 'periodFrom', 'FromDate', 'fromDate', 'StartDate', 'startDate'],
  periodTo: ['PeriodTo', 'periodTo', 'ToDate', 'toDate', 'EndDate', 'endDate'],
  revenueType: ['RevenueType', 'revenueType', 'RevenueTypeText', 'revenueTypeText', 'TaxType', 'taxType'],
  dueDate: ['DueDate', 'dueDate', 'FilingDueDate', 'filingDueDate', 'DueDateText', 'dueDateText'],
  receivedDate: ['ReceivedDate', 'receivedDate', 'SubmissionDate', 'submissionDate', 'ReceivedDateText']
});

/**
 * Property-name aliases for a bound forms row.
 *
 * @type {ReadonlyObject<string, Array<string>>}
 */
const FORMS_FIELD_ALIASES = Object.freeze({
  formTitle: ['FormTitle', 'formTitle', 'Name', 'name', 'FormName', 'formName', 'Title', 'title'],
  period: ['Period', 'period', 'PeriodName', 'periodName', 'PeriodText', 'periodText'],
  status: ['Status', 'status', 'StatusText', 'statusText', 'FormStatus', 'formStatus'],
  periodFrom: ['PeriodFrom', 'periodFrom', 'FromDate', 'fromDate'],
  periodTo: ['PeriodTo', 'periodTo', 'ToDate', 'toDate'],
  revenueType: ['RevenueType', 'revenueType', 'TaxType', 'taxType'],
  dueDate: ['DueDate', 'dueDate', 'FilingDueDate', 'filingDueDate'],
  receivedDate: ['ReceivedDate', 'receivedDate', 'SubmissionDate', 'submissionDate']
});

/**
 * Coerces a bound value into the shape the pipeline expects.
 *
 * Dates come through as real Date objects (UI5) or as ISO strings (OData), and
 * both must land as `YYYY-MM-DD`. Leaving a raw Date in place would mean every
 * downstream date comparison re-implemented the coercion, which is exactly the
 * class of bug this rework is removing.
 *
 * @param {unknown} value
 * @returns {string}
 */
function coerceDateValue(value) {
  if (value === undefined || value === null || value === '') return '';

  if (value instanceof Date) {
    return Number.isNaN(value.getTime()) ? '' : value.toISOString().split('T')[0];
  }

  if (typeof value === 'number' && Number.isFinite(value)) {
    // Epoch milliseconds, which is how some OData v2 services encode dates.
    const fromEpoch = new Date(value);
    return Number.isNaN(fromEpoch.getTime()) ? '' : fromEpoch.toISOString().split('T')[0];
  }

  const text = String(value).trim();
  // `2026-11-30T00:00:00.000Z` and `2026/11/30` both reduce to the same key.
  const iso = /^(\d{4})[/-](\d{1,2})[/-](\d{1,2})/.exec(text);
  if (iso) {
    return `${iso[1]}-${String(iso[2]).padStart(2, '0')}-${String(iso[3]).padStart(2, '0')}`;
  }
  return text;
}

/**
 * Maps bound model objects onto pipeline field names.
 *
 * The first alias present wins. An object that yields no recognisable field at
 * all is reported through `__extraction_error`, never as a row of blanks.
 *
 * @param {ReadonlyObject<string, Array<string>>} aliases
 * @param {Array<Object>} boundRows
 * @param {Set<string>} [dateFields] - fields to run through coerceDateValue
 * @returns {{rows: Array<Object>, unmappedObjects: number}}
 */
function mapBoundObjects(aliases, boundRows, dateFields) {
  const list = Array.isArray(boundRows) ? boundRows : [];
  const dates = dateFields instanceof Set ? dateFields : new Set(['dueDate', 'receivedDate', 'periodFrom', 'periodTo']);
  const out = [];
  let unmappedObjects = 0;

  for (const bound of list) {
    if (!bound || typeof bound !== 'object') {
      unmappedObjects += 1;
      out.push({ __extraction_error: 'no_binding_object' });
      continue;
    }

    // A marker from the extractor carries a more precise reason than anything
    // the mapper could infer, so it is passed through rather than overwritten.
    if (typeof bound.__extraction_error === 'string') {
      unmappedObjects += 1;
      out.push(bound);
      continue;
    }

    const record = {};
    let filled = 0;
    for (const [field, candidates] of Object.entries(aliases || {})) {
      let value = '';
      for (const key of candidates) {
        if (bound[key] !== undefined && bound[key] !== null && bound[key] !== '') {
          value = bound[key];
          break;
        }
      }
      if (value === '') continue;
      record[field] = dates.has(field) ? coerceDateValue(value) : String(value).trim();
      filled += 1;
    }

    if (filled === 0) {
      unmappedObjects += 1;
      out.push(Object.assign({ __extraction_error: 'no_recognised_fields' }, { __sampleKeys: Object.keys(bound).slice(0, 6) }));
      continue;
    }

    out.push(record);
  }

  return { rows: out, unmappedObjects };
}

/**
 * Whether a page exposes the methods the helpers need.
 *
 * The scrapers accept a plain page object in tests and, historically, accepted
 * partial pages in production. Checking up front means a caller without
 * `waitForFunction` gets the legacy path instead of a TypeError partway through.
 *
 * @param {Object} page
 * @returns {boolean}
 */
function supportsUi5Helpers(page) {
  return Boolean(
    page
    && typeof page.evaluate === 'function'
    && typeof page.url === 'function'
    && typeof page.waitForFunction === 'function'
  );
}

/**
 * Fields that must end up as YYYY-MM-DD whichever strategy produced them.
 * Without this the DOM path would return "2026/11/30" while the binding path
 * returns "2026-11-30", and every downstream comparison would have to accept
 * both.
 * @type {Set<string>}
 */
const DATE_FIELDS = new Set(['dueDate', 'receivedDate', 'periodFrom', 'periodTo']);

/**
 * Normalises the date fields of already-mapped rows.
 * @param {Array<Object>} rows
 * @returns {Array<Object>}
 */
function normalizeDateFields(rows) {
  const list = Array.isArray(rows) ? rows : [];
  return list.map((row) => {
    if (!row || typeof row !== 'object') return row;
    const out = Object.assign({}, row);
    for (const field of DATE_FIELDS) {
      if (out[field]) out[field] = coerceDateValue(out[field]);
    }
    return out;
  });
}

/**
 * Reads a portal table's rows, preferring the bound model and falling back to
 * the DOM.
 *
 * Order matters. The bound object is the stable source: real values, immune to
 * column reordering. The DOM read is the fallback for a control whose binding is
 * unavailable, and it is mapped by header text rather than position.
 *
 * @param {import('playwright').Page} page
 * @param {Object} options
 * @param {string} [options.tableIdSuffix] - stable UI5 control id suffix
 * @param {ReadonlyArray<{header: string, field: string}>} [options.headerMap]
 * @param {ReadonlyObject<string, Array<string>>} [options.aliases]
 * @param {string} [options.rowSelector]
 * @param {number} [options.maxRows=200]
 * @returns {Promise<{ok: boolean, rows: Array<Object>, strategy: string, total: number,
 *   truncated: boolean, reason?: string, unmapped?: number}>}
 */
async function readPortalRows(page, options = {}) {
  const tableIdSuffix = typeof options.tableIdSuffix === 'string' ? options.tableIdSuffix : '';
  const headerMap = options.headerMap || [];
  const aliases = options.aliases || {};
  const rowSelector = typeof options.rowSelector === 'string' && options.rowSelector.length > 0
    ? options.rowSelector
    : 'tr.sapMListTblRow:not(.sapMListTblHeader)';
  const maxRows = Number.isInteger(options.maxRows) && options.maxRows > 0
    ? Math.min(options.maxRows, MAX_EXTRACTED_ROWS)
    : 200;

  const domResult = async (bindingReason) => {
    const table = await extractUi5Table(page, rowSelector, maxRows).catch(() => null);
    if (!table || !table.ok) {
      return {
        ok: false,
        rows: [],
        strategy: 'none',
        total: 0,
        truncated: false,
        reason: bindingReason || 'table_unreadable'
      };
    }
    const mapped = mapRowsByHeader(headerMap, table.headers, table.rows);
    return {
      ok: true,
      rows: normalizeDateFields(mapped.rows),
      strategy: 'dom',
      total: table.total,
      truncated: table.total > mapped.rows.length,
      unmapped: 0,
      // Retained so a caller can see that the binding path was tried first and
      // why it did not work out.
      reason: bindingReason
    };
  };

  // 1. The bound model — the stable source.
  if (tableIdSuffix && supportsUi5Helpers(page)) {
    const binding = await readUi5ListBinding(page, tableIdSuffix, maxRows).catch((err) => ({
      ok: false,
      reason: err.message,
      rows: []
    }));

    if (binding.ok) {
      const mapped = mapBoundObjects(aliases, binding.rows);
      return {
        ok: true,
        rows: normalizeDateFields(mapped.rows),
        strategy: 'binding',
        total: binding.total,
        truncated: binding.truncated,
        unmapped: mapped.unmappedObjects
      };
    }

    return domResult(binding.reason);
  }

  // 2. No usable registry or no id suffix: the DOM is the only option.
  return domResult(undefined);
}

/**
 * Finds a list control by what it binds, not by what it is called.
 *
 * This exists because the configured id suffixes are informed guesses. SAP
 * renames generated view ids between releases, and a stale suffix does not
 * raise — it silently falls through to the DOM path, which still returns rows
 * but only the formatted text. So the wrong suffix degrades quality quietly
 * instead of failing loudly.
 *
 * The search scores every list control in the registry by how many of the
 * expected fields its bound rows actually populate, and keeps the best. A
 * control with unrelated rows scores zero and is rejected, which is what stops
 * this from picking whatever list happens to be first on the screen.
 *
 * @param {import('playwright').Page} page
 * @param {Object} options
 * @param {ReadonlyObject<string, Array<string>>} options.aliases
 * @param {string[]} options.expectedFields - fields a match must populate
 * @param {number} [options.probeRows=3]
 * @param {number} [options.maxCandidates=40]
 * @returns {Promise<{ok: boolean, id: string, score: number, considered: number, reason?: string}>}
 */
async function discoverTableId(page, options = {}) {
  if (!page || typeof page.evaluate !== 'function') {
    throw new TypeError('discoverTableId requires a Playwright page');
  }
  const aliases = options.aliases || {};
  const expectedFields = Array.isArray(options.expectedFields) && options.expectedFields.length > 0
    ? options.expectedFields
    : ['formTitle'];
  const probeRows = Number.isInteger(options.probeRows) && options.probeRows > 0
    ? Math.min(options.probeRows, 10)
    : 3;
  const maxCandidates = Number.isInteger(options.maxCandidates) && options.maxCandidates > 0
    ? Math.min(options.maxCandidates, 200)
    : 40;

  // Candidate ids, read once from the registry. Cheap: no rows are touched.
  const listed = await page.evaluate((maxCandidates) => {
    const ui5 = window.sap && window.sap.ui && window.sap.ui.core;
    if (!ui5 || !ui5.Element || !ui5.Element.registry) {
      return { ok: false, ids: [] };
    }
    const ids = [];
    for (const element of ui5.Element.registry) {
      if (ids.length >= maxCandidates) break;
      if (typeof element.getId !== 'function' || typeof element.getItems !== 'function') continue;
      let id = null;
      try {
        id = element.getId();
      } catch (_) {
        continue;
      }
      // An id with no `__` marker is a developer-assigned one, which is exactly
      // the stable case worth preferring.
      if (typeof id === 'string' && id.length > 0) ids.push(id);
    }
    return { ok: true, ids };
  }, maxCandidates).catch((err) => ({ ok: false, ids: [], reason: err.message }));

  if (!listed.ok || !Array.isArray(listed.ids) || listed.ids.length === 0) {
    return { ok: false, id: '', score: 0, considered: 0, reason: listed.reason || 'no_list_controls' };
  }

  let best = null;
  let considered = 0;

  for (const id of listed.ids) {
    // Reading three rows per candidate is bounded and cheap; the candidate set
    // is capped above so a screen with many lists cannot make this slow.
    const probe = await readUi5ListBinding(page, id, probeRows).catch(() => null);
    if (!probe || !probe.ok || probe.rows.length === 0) continue;
    considered += 1;

    const mapped = mapBoundObjects(aliases, probe.rows);
    let score = 0;
    for (const row of mapped.rows) {
      if (row.__extraction_error) continue;
      for (const field of expectedFields) {
        if (row[field] !== undefined && row[field] !== '') score += 1;
      }
    }

    if (score === 0) continue;
    // Ties go to the shorter id: among equally good candidates the more stable
    // one is the one the portal names explicitly.
    if (!best || score > best.score || (score === best.score && id.length < best.id.length)) {
      best = { id, score };
    }
  }

  if (!best) {
    return { ok: false, id: '', score: 0, considered, reason: 'no_control_matched_expected_fields' };
  }

  return { ok: true, id: best.id, score: best.score, considered };
}

/**
 * Process-lifetime cache of discovered table ids, keyed by purpose.
 *
 * Discovery runs once per purpose per process rather than per account, because
 * a single portal session serves every account on the run and the control id
 * cannot change mid-session.
 *
 * @type {Map<string, string>}
 */
const DISCOVERED_TABLE_IDS = new Map();

/**
 * Resolves the table id for a purpose, preferring the configured suffix.
 *
 * The configured suffix is tried first because it is one lookup. Discovery runs
 * only when it misses, and its result is cached so the cost is paid once.
 *
 * @param {import('playwright').Page} page
 * @param {Object} options
 * @param {string[]} options.configuredSuffixes
 * @param {string} options.cacheKey
 * @param {ReadonlyObject<string, Array<string>>} options.aliases
 * @param {string[]} options.expectedFields
 * @returns {Promise<{id: string, via: 'configured'|'cache'|'discovery', discovered: boolean, reason?: string}>}
 */
async function resolveTableId(page, options = {}) {
  const configured = Array.isArray(options.configuredSuffixes) ? options.configuredSuffixes : [];
  const cacheKey = typeof options.cacheKey === 'string' ? options.cacheKey : '';

  // A previously discovered id is trusted for the rest of the session. It is
  // verified on the next read anyway, since the id must resolve to a control.
  if (cacheKey && DISCOVERED_TABLE_IDS.has(cacheKey)) {
    return { id: DISCOVERED_TABLE_IDS.get(cacheKey), via: 'cache', discovered: true };
  }

  for (const suffix of configured) {
    const probe = await readUi5ListBinding(page, suffix, 1).catch(() => null);
    if (probe && probe.ok) {
      return { id: suffix, via: 'configured', discovered: false };
    }
  }

  const found = await discoverTableId(page, {
    aliases: options.aliases,
    expectedFields: options.expectedFields
  });

  if (found.ok) {
    if (cacheKey) DISCOVERED_TABLE_IDS.set(cacheKey, found.id);
    return { id: found.id, via: 'discovery', discovered: true };
  }

  return { id: '', via: 'none', discovered: false, reason: found.reason };
}

/**
 * Clears the discovered-id cache.
 *
 * Exported for tests and for a future "reload the portal" path, where a cached
 * id from a previous page load could be stale.
 *
 * @returns {void}
 */
function clearDiscoveredTableIds() {
  DISCOVERED_TABLE_IDS.clear();
}

